<script setup lang="ts">
import {computed} from 'vue'
import {useResearchStore} from '../stores/research'
import {useBackendStore} from '../stores/backend'
import {useCopilotStore} from '../stores/copilot'
import {useComposerStore} from '../stores/composer'
import {paperUrl} from '../lib/paperSources'
const research=useResearchStore(),backend=useBackendStore(),copilot=useCopilotStore(),composer=useComposerStore()
const emit=defineEmits<{notes:[]}>()
const draft=computed(()=>composer.forSpace(backend.user?.id||'guest',research.activeId||'default'))
const title=computed(()=>draft.value.references.length?'本次引用 '+draft.value.references.length+' 项资料':draft.value.ignoreCanvas?'未引用画布选择':copilot.context==='relation'?'研究联系 · 非真实引用':copilot.sources.length===1?copilot.sources[0]!.title:copilot.sources.length>1?'已选择 '+copilot.sources.length+' 篇论文':research.question||'从一个研究问题开始')
const localCount=computed(()=>copilot.sources.filter(s=>research.paperById(s.id)?.localDocumentId||s.documentId).length)
function removePdf(id:string){const doc=backend.attached.find(d=>d.id===id);backend.attached=backend.attached.filter(d=>d.id!==id);draft.value.references=draft.value.references.filter(r=>r.kind!=='document'||r.id!==doc?.localId)}
</script>
<template><details class="research-context-card"><summary><span class="context-caption">研究上下文</span><strong :title="title">{{title}}</strong><small>{{backend.attached.length}} 份 PDF 已绑定<span v-if="draft.references.length"> · 本次引用以输入框标签为准</span><span v-else-if="!draft.ignoreCanvas&&copilot.sources.length"> · {{localCount}} 篇可提供 PDF / {{copilot.sources.length-localCount}} 篇仅元数据</span></small></summary><div class="research-context-details">
<p v-if="research.question">研究问题：{{research.question}}</p><p>普通对话仅发送标签中的资料与明确选择的题录；本地 PDF 不会因出现在画布中而自动上传。点击精读/对比时将解析所选论文的已绑定 PDF。</p><label><input v-model="draft.ignoreCanvas" type="checkbox"/>普通对话不引用画布选择</label>
<section v-for="reference in draft.references" :key="reference.kind+reference.id"><strong>{{reference.name}}</strong><small>{{reference.kind==='document'?'本地 PDF · 发送时提供并解析':reference.kind==='note'?'用户保存的笔记快照 · 非论文原文':'明确引用的论文题录'}}</small><button class="text-button" :aria-label="'移除上下文引用 '+reference.name" @click="draft.references=draft.references.filter(r=>r.kind!==reference.kind||r.id!==reference.id)">移除此引用</button></section><label>结构化分析来源<select v-model="copilot.sourceMode" :disabled="copilot.busy"><option value="papers">当前画布选择</option><option value="materials">明确提供的 PDF（{{backend.attached.length}}）</option></select></label>
<section v-for="source in copilot.sources" :key="source.id"><strong>{{source.title}}</strong><small>{{source.documentId?'PDF 已绑定 · 实际范围以任务解析结果为准':research.paperById(source.id)?.localDocumentId?'本地 PDF 可用 · 分析时解析':'仅元数据 · 不可确认全文实验结论'}}</small><template v-if="research.paperById(source.id)"><select :value="copilot.bindings[source.id]||''" :disabled="copilot.busy" :aria-label="source.title+' 的 PDF 来源绑定'" @change="copilot.bindings[source.id]=($event.target as HTMLSelectElement).value"><option value="">使用论文已有绑定；无 PDF 时有限分析</option><option v-for="doc in backend.attached" :key="doc.id" :value="doc.id">{{doc.name}}</option></select><div class="button-row"><a v-if="paperUrl(research.paperById(source.id)!,research.activeId||'default')" :href="paperUrl(research.paperById(source.id)!,research.activeId||'default')" target="_blank" rel="noopener noreferrer">打开原文 ↗</a><button class="text-button" @click="research.editPaper(source.id)">编辑资料</button><button class="text-button" @click="research.requestRemoval(source.id,'paper')">移除卡片</button><button v-if="research.paperById(source.id)?.localDocumentId" class="text-button" @click="research.requestRemoval(research.paperById(source.id)!.localDocumentId!,'document')">删除浏览器 PDF</button><button v-if="research.paperById(source.id)?.localDocumentId" class="text-button" :disabled="copilot.busy" @click="research.organizePapers([source.id],false)">重试题录</button></div><details v-if="research.paperById(source.id)?.metadataEvidence?.length"><summary>题录的原文依据</summary><p v-for="(e,i) in research.paperById(source.id)!.metadataEvidence" :key="i">PDF 第 {{e.page}} 页：{{e.quote}}</p></details></template></section>
<p v-if="research.selectedRelationDetail">{{research.selectedRelationDetail.reason}}<br/>AI 主题联系，需人工核验，不表示真实引用。</p><div v-for="doc in backend.attached" :key="doc.id" class="context-document"><span>{{doc.name}} · {{doc.parseStatus==='text_ready'?'已解析片段':doc.parseStatus==='text_truncated'?'有限片段':'证据不足'}}</span><button class="text-button" :disabled="backend.busy" :aria-label="'移除来源 '+doc.name" @click="removePdf(doc.id)">移除</button></div><button class="text-button" @click="emit('notes')">查看当前空间笔记</button></div></details></template>